const response = $input.first().json;
if (response.status !== 'completed') throw new Error(`OpenAI response incomplete: ${response.status ?? 'unknown'}`);
const output = (response.output ?? []).flatMap((item) => item.content ?? []).find((item) => item.type === 'output_text')?.text;
if (!output || typeof output !== 'object') throw new Error('Structured job facts are missing');
return [{ json: { facts: output, jobFactsExecution: { step: 'job_facts', model: response.model ?? 'gpt-5.4-mini-2026-03-17', promptVersion: 'job-facts-v1', responseId: response.id ?? null, inputTokens: response.usage?.input_tokens ?? 0, outputTokens: response.usage?.output_tokens ?? 0, latencyMs: Math.max(0, Date.now() - $('공고 사실 분석 준비').first().json.startedAt), attemptCount: 1 }, comparisonStartedAt: Date.now() } }];

const crypto = require('crypto');
const payload = $('HMAC 요청 검증').first().json.payload;
const response = $input.first().json;
if (response.status !== 'completed') throw new Error(`OpenAI response incomplete: ${response.status ?? 'unknown'}`);
const comparison = (response.output ?? []).flatMap((item) => item.content ?? []).find((item) => item.type === 'output_text')?.text;
if (!comparison || typeof comparison !== 'object') throw new Error('Structured profile comparison is missing');
const facts = $('공고 사실 결과 확정').first().json.facts;
const statuses = new Map((comparison.matches ?? []).map((item) => [item.requirementId, item.status]));
const ratio = (kind) => { const items = (facts.requirements ?? []).filter((item) => item.kind === kind); if (!items.length) return null; const weights = { matched: 1, partial: 0.5, missing: 0, unknown: 0 }; return items.reduce((sum, item) => sum + (weights[statuses.get(item.id)] ?? 0), 0) / items.length; };
const required = ratio('required');
const preferred = ratio('preferred');
const fitScore = required === null && preferred === null ? 0 : required === null ? Math.round(preferred * 100) : preferred === null ? Math.round(required * 100) : Math.round((required * 0.7 + preferred * 0.3) * 100);
const previous = $('공고 사실 결과 확정').first().json;
const callback = { schemaVersion: '1.0.0', eventId: crypto.randomUUID(), requestId: payload.requestId, analysisJobId: payload.analysisJobId, status: 'succeeded', result: { job: facts, comparison, fitScore }, executions: [previous.jobFactsExecution, { step: 'profile_comparison', model: response.model ?? 'gpt-5.4-mini-2026-03-17', promptVersion: 'profile-match-v1', responseId: response.id ?? null, inputTokens: response.usage?.input_tokens ?? 0, outputTokens: response.usage?.output_tokens ?? 0, latencyMs: Math.max(0, Date.now() - previous.comparisonStartedAt), attemptCount: 1 }], occurredAt: new Date().toISOString() };
return [{ json: { callback, callbackPath: payload.callbacks.resultPath } }];
